#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
cd "$REPO_ROOT"

echo "[CARLOS v2.1] Sync main..."
git pull --ff-only origin main

if ! git merge-base --is-ancestor 694e25b HEAD; then
  echo "STOP: baza repo nie zawiera oczekiwanego commita 694e25b. Nic nie zmieniono." >&2
  exit 2
fi

write_b64() {
  local target="$1"
  local payload="$2"
  printf '%s' "$payload" | base64 -d > "$target"
}

echo "[CARLOS v2.1] src/main.jsx"
write_b64 'src/main.jsx' ''

echo "[CARLOS v2.1] src/parse.js"
write_b64 'src/parse.js' ''

echo "[CARLOS v2.1] src/parse.test.js"
write_b64 'src/parse.test.js' ''

echo "[CARLOS v2.1] src/styles.css"
write_b64 'src/styles.css' ''


echo "[CARLOS v2.1] Kontrola składni..."
node --check src/parse.js

if [ ! -d node_modules ]; then
  echo "[CARLOS v2.1] Instaluję zależności..."
  npm install
fi

echo "[CARLOS v2.1] Testy..."
npm test

echo "[CARLOS v2.1] Build..."
npm run build

# dist i node_modules są lokalnymi artefaktami — nigdy nie trafiają do commita.
rm -rf dist

git add src/main.jsx src/parse.js src/parse.test.js src/styles.css

# Skrypt jest tylko nośnikiem wdrożenia. Jeśli został dodany do repo, usuń go w tym samym finalnym commicie.
if git ls-files --error-unmatch CARLOS-v2.1-apply.sh >/dev/null 2>&1; then
  git rm -f CARLOS-v2.1-apply.sh
fi

git diff --cached --check

if git diff --cached --quiet; then
  echo "Brak zmian do commita — v2.1 wygląda na już zastosowane."
  exit 0
fi

echo "[CARLOS v2.1] Commit + push..."
git commit -m "Fix Training Log mapping and mobile UI"
git push origin main

echo
echo "=== CARLOS v2.1 GOTOWE ==="
echo "SHA: $(git rev-parse --short HEAD)"
echo "Testy i build: OK"
echo "Vercel powinien automatycznie rozpocząć deployment."
